use std::{
    os::unix::fs::symlink,
    process::{Command, Stdio},
    time::{SystemTime, UNIX_EPOCH},
};

use super::*;

// conformance: no generated byte records a location outside the repository.

fn git(dir: &Path, args: &[&str]) {
    let status = Command::new("git")
        .args(args)
        .current_dir(dir)
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .status()
        .unwrap();
    assert!(status.success());
}

fn repo_root(label: &str) -> std::path::PathBuf {
    let stamp = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos();
    let root = env::temp_dir()
        .join(format!("{label}-{}-{stamp}", std::process::id()))
        .join("sim-fixture");
    fs::create_dir_all(&root).unwrap();
    let status = Command::new("git")
        .args(["init", "--quiet"])
        .current_dir(&root)
        .stdout(Stdio::null())
        .status()
        .unwrap();
    assert!(status.success());
    root.canonicalize().unwrap()
}

#[test]
fn repository_relative_content_is_published() {
    let repo = Path::new("/work/constellation/sim-fixture");
    for (name, content) in [
        (
            "provenance.json",
            r#"{"api_docs":"target/doc/","manifest":"crates/a/Cargo.toml"}"#,
        ),
        (
            "repo-contract.md",
            "see `src/lib.rs` and https://github.com/sim-nest/sim-fixture/tree/main",
        ),
        ("README.md", "a / b and and/or, `//` comments, ratio 1/2"),
    ] {
        guard(repo, name, content).unwrap();
    }
}

#[test]
fn any_local_or_embedded_outside_path_is_refused() {
    let repo = Path::new("/work/constellation/sim-fixture");
    for (name, content) in [
        (
            "provenance.json",
            r#"{"manifest":"../sim-private/.meta-workspace/Cargo.toml"}"#,
        ),
        (
            "provenance.json",
            r#"{"resolver":{"manifest":"/opt/meta/Cargo.toml"}}"#,
        ),
        (
            "repo-contract.json",
            r#"{"packages":[{"src":"crates/../../x.rs"}]}"#,
        ),
        ("repo-contract.json", r#"{"home":"~/cache"}"#),
        (
            "repo-contract.md",
            "built in /work/constellation/sim-private",
        ),
        (
            "sim-index-fragment.sx",
            "(unit /work/constellation/sim-fixture/src)",
        ),
        ("crate-catalog.md", "Built from /srv/private/x."),
        ("README.md", "cache at ~/.cargo/registry"),
        ("README.md", "copied from C:\\Users\\bo\\sim"),
        ("README.md", "share \\\\build-host\\drop"),
        (
            "validation-matrix.md",
            "`cargo check --manifest-path /srv/x/Cargo.toml`",
        ),
    ] {
        let err = guard(repo, name, content).unwrap_err();
        assert!(err.contains(name), "{content}: {err}");
    }
}

#[test]
fn no_repository_content_can_approve_a_path_it_contains() {
    // Neither a tracked nor an untracked file's text makes a path publishable:
    // permission comes only from the reviewed table.
    let repo = repo_root("publication-consumed");
    fs::write(
        repo.join("features.toml"),
        "summary = \"see /srv/private/customer for the data\"\n",
    )
    .unwrap();
    fs::write(
        repo.join("tests.rs"),
        "assert!(parse(\"/tmp/sim-demo\"));\n",
    )
    .unwrap();
    fs::write(repo.join("quote.md"), "in /srv/quoted/place\n").unwrap();
    git(&repo, &["add", "tests.rs", "quote.md"]);
    let scope = crate::owned::enter(&repo).unwrap();

    crate::owned::read_to_string(repo.join("tests.rs")).unwrap();
    assert!(crate::owned::read_to_string(repo.join("features.toml")).is_err());
    let err = guard(&repo, "README.md", "data lives in /srv/private/customer").unwrap_err();
    assert!(err.contains("/srv/private/customer"), "{err}");
    // A tracked file quoting a path outside the table is not enough either.
    crate::owned::read_to_string(repo.join("quote.md")).unwrap();
    assert!(guard(&repo, "README.md", "`/srv/quoted/place`").is_err());
    // Even a file's own quoted path stays refused; only the table admits.
    assert!(guard(&repo, "README.md", "`/tmp/sim-demo`").is_err());
    guard(&repo, "README.md", "`/scratch/tmp`").unwrap();

    assert!(scope.finish().is_err(), "the untracked read is refused");
    fs::remove_dir_all(repo.parent().unwrap()).unwrap();
}

#[test]
fn only_exact_reviewed_literals_are_public() {
    let repo = Path::new("/work/constellation/sim-fixture");
    for literal in PUBLIC_LITERALS {
        assert!(is_public_path(literal), "{literal}");
        guard(repo, "README.md", &format!("see `{literal}` here")).unwrap();
        // A literal is exact: never a prefix of something longer.
        if literal.starts_with('/') {
            assert!(!is_public_path(&format!("{literal}/x")), "{literal}");
            assert!(!is_public_path(&format!("{literal}-secret")), "{literal}");
        }
    }
    // No root, prefix, or pattern is public: every one of these is a
    // machine-local or free-form location.
    for path in [
        "/tmp/customer-secret",
        "/tmp/sim-demo",
        "/var/lib/private-job",
        "/var/runner-4711/work",
        "/etc/passwd",
        "/run/user/1000/bus",
        "/usr/local/private/tool",
        "/proc/self/environ",
        "/dev/null",
        "/srv/private/customer",
        "/home/bo/x",
        "/Users/bo/x",
        "/opt/meta/Cargo.toml",
        "/opt/viture/other.so",
        "/unreviewed/route",
        "/scratch/tmp/../etc",
        "/tmp/../etc/passwd",
        "~/.cargo/registry",
        "C:/Users/bo/x",
    ] {
        assert!(!is_public_path(path), "{path}");
        assert!(
            guard(repo, "README.md", &format!("`{path}`")).is_err(),
            "{path}"
        );
    }
    for literal in PUBLIC_LITERALS {
        let root = literal.trim_start_matches('/').split('/').next().unwrap();
        assert!(
            !NEVER_PUBLIC_ROOTS.contains(&root),
            "{literal} names a machine"
        );
    }
}

#[test]
fn a_json_schema_pointer_fragment_is_reviewed() {
    let repo = Path::new("/work/constellation/sim-fixture");
    let example = "\"#/$defs/node\"";
    assert_eq!(path_tokens(example), ["/$defs/node"]);
    guard(repo, "docs/humans/README.md", example).unwrap();
    let longer = "\"#/$defs/node/extra\"";
    assert!(guard(repo, "docs/humans/README.md", longer).is_err());
}

#[test]
fn a_protocol_route_literal_is_exact_and_a_url_is_not_a_path() {
    let repo = Path::new("/work/constellation/sim-fixture");
    // The fingerprint quotes the route the same way the generated claims do.
    guard(
        repo,
        "sim-index-fragment.claims.sx",
        r#"GatewayRequest::get(\"/v1/models\")"#,
    )
    .unwrap();
    guard(
        repo,
        "docs/humans/README.md",
        r#"request_path: \"/api/chat\""#,
    )
    .unwrap();
    guard(
        repo,
        "docs/humans/README.md",
        r#"request_path: \"/chat/completions\""#,
    )
    .unwrap();
    guard(
        repo,
        "sim-index-fragment.claims.sx",
        r#"uri:\"sim://citizen/resource\".to_owned()"#,
    )
    .unwrap();
    for path in [
        "/v1/models/admin",
        "/v1/chat/completions",
        "/v1/models/../etc/passwd",
    ] {
        assert!(!is_public_path(path), "{path}");
        assert!(
            guard(repo, "sim-index-fragment.claims.sx", &format!("`{path}`")).is_err(),
            "{path}"
        );
    }
}

#[test]
fn parent_markers_are_not_trimmed_into_a_reviewed_literal() {
    let repo = Path::new("/work/constellation/sim-fixture");
    for content in [
        "/v1/models..",
        "/v1/models\\..",
        "`/v1/models..`",
        "`/v1/models\\..`",
        "see /v1/models.. in claims",
        "/api/chat..",
        "/chat/completions\\..",
        "/proc/cpuinfo..",
        "/etc/os-release\\..",
    ] {
        let tokens = path_tokens(content);
        assert!(
            tokens
                .iter()
                .all(|token| token.contains("..") && !is_public_path(token)),
            "{content} -> {tokens:?}"
        );
        assert!(
            guard(repo, "sim-index-fragment.claims.sx", content).is_err(),
            "{content}"
        );
    }
    // One sentence dot is still punctuation, not a parent marker.
    guard(repo, "sim-index-fragment.claims.sx", "quoted /v1/models.").unwrap();
    guard(repo, "README.md", "(x \"\\\"/etc/os-release\\\"\")").unwrap();
}

