#[test]
fn writes_never_follow_a_symlink() {
    let repo = repo_root("publication-write");
    let outside = repo.parent().unwrap().join("outside");
    fs::create_dir_all(&outside).unwrap();
    symlink(&outside, repo.join("docs")).unwrap();
    symlink(outside.join("x.md"), repo.join("linked.md")).unwrap();
    let scope = crate::owned::enter(&repo).unwrap();

    let err = write(&repo, &repo.join("docs/generated/a.md"), "ok").unwrap_err();
    assert!(err.contains("is a symlink"), "{err}");
    let err = write(&repo, &repo.join("linked.md"), "ok").unwrap_err();
    assert!(err.contains("is a symlink"), "{err}");
    write(&repo, &repo.join("plain/a.md"), "ok").unwrap();
    assert_eq!(fs::read_to_string(repo.join("plain/a.md")).unwrap(), "ok");
    assert!(!outside.join("generated").exists());
    scope.finish().unwrap();
    fs::remove_dir_all(repo.parent().unwrap()).unwrap();
}

#[test]
fn path_tokens_find_unix_windows_and_home_paths_but_not_urls() {
    assert_eq!(
        path_tokens("a /srv/x/y, `C:\\Users\\a` \"~/.cargo/x\" https://h/p/q (\\\\h\\s)"),
        ["/srv/x/y", "C:\\Users\\a", "~/.cargo/x", "\\\\h\\s"]
    );
    assert!(path_tokens("src/lib.rs a/b /single // x").is_empty());
    // Relative paths and URLs are not absolute-path starts.
    assert!(
        path_tokens("crates/a/src/x.rs https://example.com/a/b ../x/y ./a/b a.b-c/d_e/f")
            .is_empty()
    );
}

/// A candidate runs through every character up to a delimiter, so a private
/// path cannot hide behind Unicode, a shell variable, or punctuation, and it
/// is published only when the whole candidate is a reviewed literal.
#[test]
fn a_candidate_is_the_whole_run_through_unicode_and_shell_punctuation() {
    let repo = Path::new("/work/constellation/sim-fixture");
    for (text, whole) in [
        ("see /tmp/\u{79d8}\u{5bc6} here", "/tmp/\u{79d8}\u{5bc6}"),
        ("`/tmp/$SECRET`", "/tmp/$SECRET"),
        ("in /tmp/${SECRET}/x now", "/tmp/${SECRET}/x"),
        ("at /var/run/\u{1f512}/k.", "/var/run/\u{1f512}/k"),
        ("cd $HOME/secret/x", "$HOME/secret/x"),
        ("cd ${SECRET_DIR}/x", "${SECRET_DIR}/x"),
        ("at ~/\u{79d8}/x", "~/\u{79d8}/x"),
        ("at /\u{79d8}/x", "/\u{79d8}/x"),
        ("=/opt/caf\u{e9}/bin/x", "/opt/caf\u{e9}/bin/x"),
        ("/tmp/a%20b/c*d", "/tmp/a%20b/c*d"),
        ("C:\\Users\\\u{79d8}\\x", "C:\\Users\\\u{79d8}\\x"),
        ("path:/tmp/customer-secret", "/tmp/customer-secret"),
        ("x$HOME/secret", "$HOME/secret"),
        ("id42$HOME/secret", "$HOME/secret"),
        ("\u{79d8}/tmp/secret", "/tmp/secret"),
        ("(x)/var/runner/work", "/var/runner/work"),
        ("dir:~/secret/x", "~/secret/x"),
    ] {
        assert_eq!(path_tokens(text), [whole], "{text}");
        assert!(guard(repo, "README.md", text).is_err(), "{text}");
    }
    // A reviewed literal followed by more is a different, unreviewed path.
    for text in ["/proc/cpuinfo\u{79d8}", "/proc/cpuinfo$X", "/proc/cpuinfo*"] {
        assert!(guard(repo, "README.md", text).is_err(), "{text}");
    }
    guard(
        repo,
        "README.md",
        "reads `/proc/cpuinfo`, then /proc/meminfo.",
    )
    .unwrap();
    // The escaped quotes of a rendered string literal are not part of the path.
    guard(repo, "README.md", "(x \"\\\"/etc/os-release\\\"\")").unwrap();
    assert!(guard(repo, "README.md", "/proc/cpuinfo\\secret").is_err());
    guard(
        repo,
        "README.md",
        "plain prose, a/b, and/or, 50/50, https://x.io/a/b",
    )
    .unwrap();
}

#[test]
fn rust_format_labels_are_not_filesystem_paths() {
    let repo = Path::new("/work/constellation/sim-fixture");
    let badge = "badge(\"{target}/{lens}/{fidelity}\")";
    assert!(path_tokens(badge).is_empty(), "{:?}", path_tokens(badge));
    guard(repo, "docs/humans/README.md", badge).unwrap();

    // The same split tail, bounded by the scanner's other label separators.
    for label in [
        "badge('{target}/{lens}/{fidelity}')",
        "badge(`{target}/{lens}/{fidelity}`)",
        "before {target}/{lens}/{fidelity} after",
        "{target}/{lens}/{fidelity}",
        "name\"{target}/{lens}/{fidelity}\"",
    ] {
        assert!(
            path_tokens(label).is_empty(),
            "{label} tokens {:?}",
            path_tokens(label)
        );
        guard(repo, "docs/humans/README.md", label).unwrap();
    }

    // Security counterexamples, plus one surrounding case for each way the
    // hole run stops being the badge. A leading slash is still a path.
    for text in [
        "/home/{user}/keys",
        "~/{secret}/x",
        "/tmp/${SECRET}/x",
        "/etc/shadow",
        "/tmp/db",
        "see }/etc/passwd now",
        "/{lens}/etc/passwd",
        "C:\\{User}\\{Secret}",
        "/{target}/{lens}/{fidelity}",
        "The route is /{target}/{lens}.",
        "name=/{lens}/{fidelity}",
        "={target}/{lens}/{fidelity}",
        "name({target}/{lens}/{fidelity}",
        "({target}/{lens}/{fidelity})",
        "notes/{target}/{lens}/{fidelity}",
        "foo{target}/{lens}/{fidelity}",
        "cache at \\{target}/{lens}/{fidelity}",
        "cache at //home/alice/{target}/{lens}/{fidelity}",
        "badge(\"{target}/{lens}/{fidelity}!\")",
        "badge(\"{target}/{lens}/{fidelity}.\")",
        "cache at {target}/{lens}/../secret",
        "cache at /{target}/{lens})/secret",
        "cache at =({target}/{lens}/{fidelity}",
    ] {
        assert!(
            guard(repo, "README.md", text).is_err(),
            "{text} tokens {:?}",
            path_tokens(text)
        );
    }
}

#[test]
fn numeric_slash_dates_are_not_filesystem_paths() {
    let repo = Path::new("/work/constellation/sim-fixture");
    // The backslash keeps the date from being read as one relative path, so
    // the scanner starts at `/08/2026`. That is the ledger statement line.
    let dated = "b\"24/08/2026;b1;12,50;;Coffee\\n25/08/2026;b2;;54,50;Invoice\\n\"";
    assert!(path_tokens(dated).is_empty(), "{:?}", path_tokens(dated));
    guard(repo, "docs/humans/README.md", dated).unwrap();
    let other = "b\"25/08/2026;x;1,00;2,00;both\\n25/08/2026;y;;;neither\\n\"";
    assert!(path_tokens(other).is_empty(), "{:?}", path_tokens(other));
    guard(repo, "docs/humans/README.md", other).unwrap();

    for label in ["x\\n25/08/2026", "x\\n2026/08/24"] {
        assert!(
            path_tokens(label).is_empty(),
            "{label} tokens {:?}",
            path_tokens(label)
        );
        guard(repo, "docs/humans/README.md", label).unwrap();
    }

    for text in [
        "/08/2026",
        "cache at /08/2026",
        "/home/{user}/keys",
        "~/{secret}/x",
        "/etc/shadow",
        "/tmp/db",
        "x\\n25/etc/passwd",
        "x\\n25/08/passwd",
        "x\\n25/08/2026!",
        "x\\n25/08/2026.",
        "x\\n25/08/2026/../secret",
    ] {
        assert!(
            guard(repo, "README.md", text).is_err(),
            "{text} tokens {:?}",
            path_tokens(text)
        );
    }
}

#[test]
fn expression_tree_table_examples_are_exact_public_literals() {
    let repo = Path::new("/work/constellation/sim-fixture");
    let specimen = r#"
        Expr::String("/dir-1/cell-1".to_owned())
        "(expr-tree/ref tree \"../base\" \"/dir-1/nested\")"
        "(expr-tree/ref tree \"/dir-1/base\")"
        Expr::String("/external/renamed".to_owned())
        "(expr-tree/rename tree \"/external/record\" \"renamed\")"
        Expr::String("/dir-1/moved".to_owned())
        path("/team/cell")
        path("/team/frozen")
        path("/team/manual")
        path("/sheet/a")
        path("/sheet/b")
        path("/sheet/c")
        path("/sheet/quoted")
        path("/sheet/total")
        path("/sheet/use")
        path("/sheet/use-remote")
        path("/sheet/use-value")
        path("/sheet/value")
        path("/secure/result")
        absolute("/results/detail")
        set_codec(&session, revision, "/model/answer", "codec/lisp")
        "/measurements/trial-0001"
        path("/chain/0")
        path("/chain/{LAST}")
        path("/chain/{index}")
        path("/chain/{}")
        path("/remote/value")
        path("/remote/moved")
        "/external/value"
        target("/archive/solve", TREE_REVISION)
        generated-dir=/dir-1 generated-cell=/dir-1/cell-1
    "#;
    let tokens = path_tokens(specimen);
    assert!(
        tokens.iter().all(|token| is_public_path(token)),
        "{tokens:?}"
    );
    guard(repo, "docs/humans/README.md", specimen).unwrap();
    assert!(!is_public_path("/unreviewed/route"));
    assert!(guard(repo, "docs/humans/README.md", "`/unreviewed/route`").is_err());
    assert!(!is_public_path("/dir-1/cell-1/extra"));
    assert!(guard(repo, "docs/humans/README.md", "`/dir-1/cell-1/extra`").is_err());
}
